const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export interface CreateUserRequest {
  name: string;
  email: string;
  password: string;
 isActive: boolean;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role:  "USER";
  isActive : boolean;
  createdAt: string;
}

export interface UpdateUserRequest {
  name: string;
  email: string;
  role: "ADMIN" | "USER" | "OPERATOR";
  isActive: boolean;
  password?: string;
}

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  users?: T;
  error?: string;
}


export async function getUsers(): Promise<ApiResponse<User[]>> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/users`, {
      credentials: "include",
      cache: "no-store",
    });

    const result = await response.json();

    return result;
  } catch (error) {
    return {
      success: false,
      error: "Failed to fetch users",
    };
  }
}
export async function createUser(
  data: CreateUserRequest
): Promise<ApiResponse> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/createUser`, {
      method: "POST",
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(data),
    });

    const result = await response.json();

    return result;
  } catch (error) {
    return {
      success: false,
      error: "Failed to create user",
    };
  }
}

export async function deleteUser(
  userId: string
): Promise<ApiResponse> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/admin/users/deleteUser/${userId}`,
      {
        method: "DELETE",
        credentials: "include",
      }
    );

    const result = await response.json();
    return result;
  } catch (error) {
    return {
      success: false,
      error: "Failed to delete user",
    };
  }
}

export async function getUserById(
  userId: string
): Promise<ApiResponse<User>> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/admin/users/${userId}`,
      {
        method: "GET",
        credentials: "include",
        cache: "no-store",
      }
    );

    const result = await response.json();

    return result;
  } catch (error) {
    return {
      success: false,
      error: "Failed to fetch user",
    };
  }
}
export async function updateUser(
  userId: string,
  data: UpdateUserRequest
): Promise<ApiResponse> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/admin/users/updateUser/${userId}`,
      {
        method: "PUT",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      }
    );

    const result = await response.json();

    return result;
  } catch {
    return {
      success: false,
      error: "Failed to update user",
    };
  }
}